package local.chuan.core;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import static local.chuan.core.Engine.*;
import static local.chuan.core.Protocol.*;

final class WebServer implements Closeable {
    final Engine e;ServerSocket listener;
    final ThreadPoolExecutor workers=new ThreadPoolExecutor(4,64,30,TimeUnit.SECONDS,new SynchronousQueue<Runnable>());
    WebServer(Engine engine){e=engine;}
    void start()throws IOException {listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(e.config.port),64);Thread thread=new Thread(()->{while(!listener.isClosed())try{Socket socket=listener.accept();socket.setSoTimeout(30000);socket.setTcpNoDelay(true);e.sockets.add(socket);try{workers.execute(()->serve(socket));}catch(RejectedExecutionException busy){response(socket.getOutputStream(),503,"Service Unavailable","服务繁忙，请稍后重试","text/plain; charset=utf-8");socket.close();e.sockets.remove(socket);}}catch(IOException ignored){}},"Chuan HTTP");thread.setDaemon(true);thread.start();}
    int port(){return listener.getLocalPort();}
    void serve(Socket socket){try{String ip=socket.getInetAddress().getHostAddress();if(!local(ip))return;InputStream input=new BufferedInputStream(socket.getInputStream());OutputStream output=new BufferedOutputStream(socket.getOutputStream());Header h=header(input);String[] first=h.first.split(" ");if(first.length!=3||(!first[2].equals("HTTP/1.1")&&!first[2].equals("HTTP/1.0")))throw new IOException("HTTP 请求行无效");String method=first[0],target=first[1],path=target.split("\\?",2)[0];
        if(!h.get("x-chuan-server").isEmpty()&&!h.get("x-chuan-server").equals(e.config.id)){response(output,409,"Conflict","服务端身份已变化，请重新连接","text/plain; charset=utf-8");return;}
        if(path.startsWith("/api/")){e.observe(h,ip);nativeRequest(socket,input,output,h,method,path,ip);return;}
        if(!e.config.shareSoftware){response(output,403,"Forbidden","Web 服务已关闭","text/plain; charset=utf-8");return;}
        if(!validHost(h)){response(output,403,"Forbidden","请使用本机 IPv4 地址和端口访问","text/plain; charset=utf-8");return;}
        Map<String,String> query=query(target);String expected=h.get("x-chuan-instance");if(expected.isEmpty())expected=query.getOrDefault("instance","");String host=query.getOrDefault("server","");
        if((!host.isEmpty()&&!host.equals(e.config.id))||(!expected.isEmpty()&&!expected.equals(e.instance))){response(output,409,"Conflict","服务端运行会话已变化，请刷新页面","text/plain; charset=utf-8");return;}
        if(path.equals("/download/Chuan.apk")){File apk=e.platform.apk();if(apk==null||!apk.isFile()){response(output,404,"Not Found","当前主机未提供 Android 安装包","text/plain; charset=utf-8");return;}try(InputStream file=new FileInputStream(apk)){download(output,file,apk.length(),"Chuan-"+VERSION+"-android.apk","application/vnd.android.package-archive");}return;}
        if(path.equals("/download/Chuan.exe")){byte[] file=asset("download/Chuan.exe",8*1024*1024);download(output,new ByteArrayInputStream(file),file.length,"Chuan.exe","application/octet-stream");return;}
        if(path.equals("/web/api/state")&&method.equals("GET")){Session session=session(h,ip,true);json(output,webState(session));return;}
        if(path.startsWith("/web/files/")&&method.equals("GET")){String client=query.getOrDefault("client",h.get("x-chuan-client"));Session session;synchronized(e.lock){session=e.sessions.get(client);}if(session==null||(!host.isEmpty()&&!query.getOrDefault("ticket","").equals(session.token))||(query.containsKey("ticket")&&!query.get("ticket").equals(session.token)))throw new IOException("浏览器下载会话已失效");long id=number(path.substring(11));String start=h.get("x-chuan-offset"),range=h.get("range");boolean ranged=start.isEmpty()&&!range.isEmpty();if(ranged){if(!range.matches("bytes=[0-9]+-"))throw new IOException("续传范围无效");start=range.substring(6,range.length()-1);}e.transfers.download(session,e.find(id),output,"trailer".equals(query.get("checksum")),start.isEmpty()?0:number(start),h.get("x-chuan-prefix"),ranged);return;}
        if(path.startsWith("/web/api/")&&method.equals("POST")){Session session=session(h,ip,false);if(!path.equals("/web/api/leave"))synchronized(e.lock){String tab=h.get("x-chuan-tab").isEmpty()?session.client:h.get("x-chuan-tab");session.tabs.put(tab,now());session.openTabs.add(tab);Peer peer=e.peers.get(session.id);if(peer!=null)peer.seen=now();}webCommand(socket,input,output,h,path,ip,session);return;}
        if(method.equals("GET")){String file=path.equals("/")?"index.html":path.startsWith("/web/")?path.substring(5):"";if(!Arrays.asList("index.html","style.css","app.js","files.js","transfers.js","sha256.js","session.js","zip_store.js","zip_worker.js","approvals.js","hash_file.js","hash_worker.js","zip_stream_worker.js").contains(file)){response(output,404,"Not Found","","text/plain");return;}byte[] bytes=asset(file,2*1024*1024);response(output,200,"OK",new String(bytes,StandardCharsets.UTF_8),mime(file));return;}
        response(output,405,"Method Not Allowed","","text/plain");
    }catch(Transfers.LimitException limit){try{response(socket.getOutputStream(),413,"Content Too Large",limit.getMessage(),"text/plain; charset=utf-8");}catch(IOException ignored){}
    }catch(FileNotFoundException missing){try{response(socket.getOutputStream(),404,"Not Found",missing.getMessage(),"text/plain; charset=utf-8");}catch(IOException ignored){}
    }catch(Exception error){try{response(socket.getOutputStream(),400,"Bad Request",error.getMessage()==null?"请求无效":error.getMessage(),"text/plain; charset=utf-8");}catch(IOException ignored){}
    }finally{e.sockets.remove(socket);try{socket.close();}catch(IOException ignored){}}}
    boolean validHost(Header h){String host=h.get("host"),origin=h.get("origin");if(!origin.isEmpty()&&!origin.equals("http://"+host))return false;int colon=host.lastIndexOf(':');if(colon<0||!host.substring(colon+1).equals(String.valueOf(e.config.port)))return false;String ip=host.substring(0,colon);return ip.equals("localhost")||ip.equals("127.0.0.1")||e.addresses().contains(ip);}
    byte[] asset(String name,int limit)throws IOException {try(InputStream input=e.platform.asset(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int count;while((count=input.read(buffer))>=0){if(out.size()+count>limit)throw new IOException("内置资源过长");out.write(buffer,0,count);}return out.toByteArray();}}
    void json(OutputStream output,Object value)throws IOException{response(output,200,"OK",Json.stringify(value),"application/json; charset=utf-8");}
    void nativeRequest(Socket socket,InputStream input,OutputStream output,Header h,String method,String path,String ip)throws IOException {
        if(path.equals("/api/info")&&method.equals("GET")){json(output,Json.map("protocol",1,"id",e.config.id,"nameHex",hex(e.config.name),"port",e.config.port,"instance",e.instance,"platform","android"));return;}
        if(method.equals("POST")&&(path.equals("/api/offer-status")||path.equals("/api/offer-cancel"))){e.transfers.offerStatus(input,output,h,ip,false,path.endsWith("cancel"));return;}
        if(path.equals("/api/offer")&&method.equals("POST")){e.transfers.offer(socket,input,output,h,ip,false);return;}
        if(method.equals("POST")&&path.startsWith("/api/retry-upload/")){e.transfers.retryUpload(output,h,ip,path.substring(18),false);return;}
        if(method.equals("POST")&&(path.equals("/api/batch-files")||path.equals("/api/batch-status"))){e.transfers.batchFiles(input,output,h,ip,null,path.endsWith("batch-status"));return;}
        if(method.equals("POST")&&path.startsWith("/api/upload-status/")){synchronized(e.lock){Batch batch=e.batches.get(e.transfers.batchKey(h,ip,false));if(batch!=null)for(Job job:e.jobs.values())if(job.nativeOwner.equals(h.get("x-chuan-id"))&&job.batchId.equals(h.get("x-chuan-batch"))&&job.upload.equals(path.substring(19))){batch.touched=now();response(output,200,"OK",String.valueOf(job.paused?7:job.state),"text/plain");return;}}response(output,404,"Not Found","","text/plain");return;}
        if(path.equals("/api/copy-probe")&&method.equals("POST")){e.transfers.upload(socket,input,output,h,ip,false,true);return;}
        if(path.equals("/api/copy-check")&&method.equals("POST")){h.fields.put("x-chuan-metadata","1");e.transfers.upload(socket,input,output,h,ip,false,true);return;}
        if(path.startsWith("/api/file-phase/")&&method.equals("POST")){e.transfers.phase(input,output,h,ip,path.substring(16),false);return;}
        if(path.startsWith("/api/pause-upload/")&&method.equals("POST")){long id=0;synchronized(e.lock){for(Job job:e.jobs.values())if(job.nativeOwner.equals(h.get("x-chuan-id"))&&job.batchId.equals(h.get("x-chuan-batch"))&&job.upload.equals(path.substring(18))){id=job.id;break;}}if(id==0)throw new FileNotFoundException();e.pause(id,!h.get("x-chuan-paused").equals("0"));json(output,Json.map());return;}
        if(path.equals("/api/resume")&&method.equals("POST")){response(output,200,"OK",Resume.probe(e,h,ip,false),"application/json");return;}
        if(path.equals("/api/upload")&&method.equals("POST")){e.transfers.upload(socket,input,output,h,ip,false);return;}
        if(path.equals("/api/mesh")){String body=method.equals("POST")?new String(read(input,h.length(),1048576),StandardCharsets.UTF_8):unhex(h.get("x-chuan-ledger"));response(output,200,"OK",e.mesh(body),"text/plain; charset=utf-8");return;}
        if(path.equals("/api/leave")&&method.equals("POST")){String id=unhex(h.get("x-chuan-id"));synchronized(e.lock){for(Job job:e.jobs.values())if(job.nativeOwner.equals(h.get("x-chuan-id"))&&!job.asyncOfferKey.isEmpty()&&job.state<3){job.cancelled=true;e.transfers.completeOffer(job,Transfers.repeat('0',job.offerItems.size()));job.error="发送端已关闭，接收请求已取消";}e.peers.values().removeIf(peer->peer.id.equals(id)||peer.owner.equals(id));}json(output,Json.map());return;}
        if(path.equals("/api/ping")&&method.equals("POST")){String target=unhex(h.get("x-chuan-target"));if(target.equals(e.config.id)){synchronized(e.lock){e.ping++;e.pingAt=now();}}else e.pingNow(e.peer(target));json(output,Json.map());return;}
        response(output,404,"Not Found","","text/plain");
    }
    String webPlatform(Header h){String kind=h.get("x-chuan-device");if(kind.equals("mobile-web")||kind.equals("desktop-web"))return kind;String agent=h.get("user-agent").toLowerCase(Locale.ROOT);return agent.matches(".*(android|iphone|ipad|ipod|mobile).*")?"mobile-web":agent.isEmpty()?"web":"desktop-web";}
    Session session(Header h,String ip,boolean register)throws IOException {
        String client=h.get("x-chuan-client");if(!key(client))throw new IOException("浏览器身份无效");synchronized(e.lock){Session session=e.sessions.get(client);if(register){String tab=h.get("x-chuan-tab");if(!tab.isEmpty()&&!key(tab))throw new IOException("页面身份无效");String name=unhex(h.get("x-chuan-name"));if(name.length()>48||name.matches(".*[\\r\\n].*"))throw new IOException("浏览器名称无效");if(session==null){if(e.sessions.size()>=128)throw new IOException("浏览器会话数量达到上限");session=new Session();session.client=client;session.id="web:"+hex(sha().digest((e.config.id+":"+client).getBytes(StandardCharsets.UTF_8))).substring(0,32);session.name=name.isEmpty()?e.config.name.substring(0,Math.min(40,e.config.name.length()))+" · 浏览器-"+client.substring(0,4):name;e.sessions.put(client,session);}session.directoryReceive=h.get("x-chuan-directory-receive").equals("1");session.ip=ip;String kind=webPlatform(h);if(!kind.equals("web")||session.platform.equals("web"))session.platform=kind;session.tabs.put(tab.isEmpty()?client:tab,now());session.openTabs.add(tab.isEmpty()?client:tab);if(!h.get("x-chuan-ping-ack").isEmpty()){long ack=number(h.get("x-chuan-ping-ack"));if(ack<=session.ping)session.ack=Math.max(session.ack,ack);}Peer peer=new Peer(session.id,session.name,ip,e.config.port);peer.browser=true;peer.directoryReceive=session.directoryReceive;peer.platform=session.platform;e.peers.put(peer.id,peer);}else if(session==null||!session.token.equals(h.get("x-chuan-token")))throw new IOException("浏览器会话已失效，请刷新页面");return session;}}
    Map<String,Object> webState(Session session){synchronized(e.lock){e.expire();List<Object> peers=new ArrayList<>(),jobs=new ArrayList<>(),requests=new ArrayList<>(),inbox=new ArrayList<>(),offers=new ArrayList<>();for(Peer peer:e.peers.values())if(!peer.id.equals(session.id))peers.add(Json.map("id",peer.id,"name",peer.name,"ip",peer.ip,"port",peer.port,"browser",peer.browser,"platform",peer.platform,"directoryReceive",peer.directoryReceive,"note",session.notes.getOrDefault(peer.ip,""),"serverId",peer.owner));
        for(Job job:e.jobs.values()){
            if(job.owner.equals(session.client)&&!job.asyncOfferKey.isEmpty())offers.add(Json.map("id",String.valueOf(job.id),"batch",job.batchId,"state",job.state,"selection",job.selection==null?"":job.selection,"error",job.error));
            if(job.hiddenClients.contains(session.client)||job.removed)continue;
            if(job.recipient.equals(session.client)&&job.requestOnly&&job.awaitingApproval){List<Object> items=new ArrayList<>();for(Item item:job.offerItems)items.add(e.itemJson(item));requests.add(Json.map("id",String.valueOf(job.id),"batch",job.batchId,"sender",job.peer,"selection",job.selection==null?"":job.selection,"items",items));}
            if(job.recipient.equals(session.client)){Map<String,Object> accepted=e.handoff(job,session);if(accepted!=null)jobs.add(accepted);}
            if(!job.requestOnly&&(job.owner.equals(session.client)||job.recipient.equals(session.client))){jobs.add(e.jobJson(job,session));if(job.recipient.equals(session.client)&&job.source!=null&&job.state!=4&&job.state!=5)inbox.add(Json.map("id",String.valueOf(job.id),"name",job.name,"size",job.total,"received",job.state==3));}
        }
        Collections.reverse(jobs);return Json.map("name",e.config.name,"version",VERSION,"platform","android","hostId",e.config.id,"serverInstance",e.instance,"token",session.token,"clientIp",session.ip,"clientName",session.name,"webUploadChecksumOptional",true,"webCopyCheck",true,"webDownloadChecksum",true,"webTransferWait",true,"webBatchFiles",true,"webUploadStatus",true,"webZipArchives",true,"webZipStream",true,"webResume",true,"webOfferAsync",true,"androidAvailable",e.platform.apk()!=null&&e.platform.apk().isFile(),"autoReceive",e.config.autoReceive,"maxTransferFiles",String.valueOf(e.config.maxFiles),"maxTransferBytes",String.valueOf(e.config.maxBytes),"ping",now()-session.pingAt<4000?session.ping:0,"hostNote","","peers",peers,"jobs",jobs,"inbox",inbox,"requests",requests,"offers",offers);
    }}
    Job owned(Session session,long id)throws IOException {synchronized(e.lock){Job job=e.jobs.get(id);if(job==null||(!job.owner.equals(session.client)&&!job.recipient.equals(session.client)))throw new IOException("任务不属于当前浏览器会话");return job;}}
    void webCommand(Socket socket,InputStream input,OutputStream output,Header h,String path,String ip,Session session)throws IOException {
        if(path.equals("/web/api/offer-cancel")){e.transfers.offerStatus(input,output,h,ip,true,true);return;}
        if(path.equals("/web/api/offer")){e.transfers.offer(socket,input,output,h,ip,true);return;}
        if(path.startsWith("/web/api/retry-upload/")){e.transfers.retryUpload(output,h,ip,path.substring(22),true);return;}
        if(path.equals("/web/api/batch-files")||path.equals("/web/api/batch-status")){e.transfers.batchFiles(input,output,h,ip,session,path.endsWith("batch-status"));return;}
        if(path.equals("/web/api/copy-probe")){e.transfers.upload(socket,input,output,h,ip,true,true);return;}
        if(path.equals("/web/api/copy-check")){h.fields.put("x-chuan-metadata","1");e.transfers.upload(socket,input,output,h,ip,true,true);return;}
        if(path.startsWith("/web/api/file-phase/")){e.transfers.phase(input,output,h,ip,path.substring(20),true);return;}
        if(path.startsWith("/web/api/archive/")){e.archives.handle(input,output,h,ip,path);return;}
        if(path.startsWith("/web/api/pause/")||path.startsWith("/web/api/resume-job/")){boolean paused=path.startsWith("/web/api/pause/");String key=path.substring(paused?15:20);Job selected=null;synchronized(e.lock){for(Job job:e.jobs.values())if((job.owner.equals(session.client)||job.recipient.equals(session.client))&&(String.valueOf(job.id).equals(key)||job.upload.equals(key))){selected=job;break;}}if(selected==null)throw new FileNotFoundException();e.pause(selected.id,paused);json(output,Json.map());return;}
        if(path.equals("/web/api/resume")){response(output,200,"OK",Resume.probe(e,h,ip,true),"application/json");return;}
        if(path.equals("/web/api/upload")){e.transfers.upload(socket,input,output,h,ip,true);return;}
        if(path.equals("/web/api/diagnostics-export")){File file=e.exportDiagnostics(session.client);try(InputStream log=new FileInputStream(file)){download(output,log,file.length(),"Chuan-diagnostics.jsonl","application/x-ndjson");}finally{file.delete();}return;}
        if(path.equals("/web/api/diagnostic")){json(output,Json.map());return;}
        if(path.startsWith("/web/api/decision/")){Job job=owned(session,number(path.substring(path.lastIndexOf('/')+1)));if(!job.recipient.equals(session.client))throw new IOException("接收审批归属不匹配");String selection=new String(read(input,h.length(),65536),StandardCharsets.US_ASCII);e.decide(job.id,selection);json(output,Json.map());return;}
        if(path.startsWith("/web/api/forward/")){Job job=e.transfers.forward(session,number(path.substring(path.lastIndexOf('/')+1)),unhex(h.get("x-chuan-peer")),h.get("x-chuan-upload"));json(output,Json.map("id",String.valueOf(job.id)));return;}
        if(path.startsWith("/web/api/file-info/")||path.startsWith("/web/api/file-saved/")||path.startsWith("/web/api/file-failed/")){
            long id=number(path.substring(path.lastIndexOf('/')+1));Job job;synchronized(e.lock){job=e.jobs.get(id);if(job==null||job.source==null||!job.recipient.equals(session.client)||job.cancelled)throw new IOException("文件不属于当前接收会话");}
            if(path.startsWith("/web/api/file-failed/")){e.state(job,5,"浏览器保存失败或存在内容冲突，原文件已保留");json(output,Json.map());return;}
            if(path.startsWith("/web/api/file-saved/")){job.done=job.total;e.state(job,3,"");response(output,200,"OK","","text/plain");return;}
            long[] tick={now()};String digest=job.directory?"":Transfers.digest(job.source.opener.open(),()->{if(job.cancelled)throw new IOException("传输已取消");if(now()-tick[0]>2000){ascii(output,"HTTP/1.1 102 Processing\r\n\r\n");tick[0]=now();}});json(output,Json.map("directory",job.directory,"sha256",digest));return;
        }
        if(path.startsWith("/web/api/upload-status/")){String upload=path.substring(23);synchronized(e.lock){for(Job job:e.jobs.values())if(job.owner.equals(session.client)&&job.upload.equals(upload)){json(output,Json.map("id",String.valueOf(job.id),"state",job.state,"paused",job.paused,"done",job.done,"error",job.error));return;}}response(output,404,"Not Found","","text/plain");return;}
        if(path.startsWith("/web/api/wait/")){Job job=owned(session,number(path.substring(path.lastIndexOf('/')+1)));long deadline=now()+2000;synchronized(e.lock){while(job.state<3&&now()<deadline&&e.running)try{e.lock.wait(200);}catch(InterruptedException error){Thread.currentThread().interrupt();break;}json(output,Json.map("id",String.valueOf(job.id),"state",job.state,"stateText",stateText(job.state),"error",job.error));}return;}
        if(path.startsWith("/web/api/cancel/")){Job job=owned(session,number(path.substring(path.lastIndexOf('/')+1)));e.cancel(job.id);json(output,Json.map());return;}
        if(path.startsWith("/web/api/delete/")){Job job=owned(session,number(path.substring(path.lastIndexOf('/')+1)));if(job.state<3)throw new IOException("请先取消活动任务");synchronized(e.lock){job.hiddenClients.add(session.client);}json(output,Json.map());return;}
        if(path.equals("/web/api/clear")){synchronized(e.lock){Set<String> active=e.busyBatches();for(Job job:e.jobs.values())if(job.state>=3&&!active.contains(job.batchId)&&job.asyncOfferKey.isEmpty()&&(job.owner.equals(session.client)||job.recipient.equals(session.client)))job.hiddenClients.add(session.client);}json(output,Json.map());return;}
        if(path.equals("/web/api/preferences")){synchronized(e.lock){session.maxFiles=number(h.get("x-chuan-max-files"));session.maxBytes=number(h.get("x-chuan-max-bytes"));}json(output,Json.map());return;}
        if(path.equals("/web/api/note")){String address=h.get("x-chuan-address"),note=unhex(h.get("x-chuan-note"));if(!local(address)||note.length()>48||note.matches(".*[\\r\\n].*"))throw new IOException("备注无效");synchronized(e.lock){session.notes.put(address,note);}json(output,Json.map());return;}
        if(path.equals("/web/api/leave")){synchronized(e.lock){String tab=h.get("x-chuan-tab").isEmpty()?session.client:h.get("x-chuan-tab");session.tabs.remove(tab);session.openTabs.remove(tab);if(session.tabs.isEmpty())e.peers.remove(session.id);e.expire();}json(output,Json.map());return;}
        if(path.equals("/web/api/ping")){String target=unhex(h.get("x-chuan-peer"));if(target.equals(e.config.id)){synchronized(e.lock){e.ping++;e.pingAt=now();}}else e.pingNow(e.peer(target));json(output,Json.map());return;}
        if(path.equals("/web/api/refresh")){e.announce();json(output,Json.map());return;}
        response(output,404,"Not Found","","text/plain");
    }
    void download(OutputStream output,InputStream input,long size,String name,String mime)throws IOException {ascii(output,"HTTP/1.1 200 OK\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Type: "+mime+"\r\nContent-Disposition: attachment; filename=\""+name+"\"\r\nContent-Length: "+size+"\r\n\r\n");copy(input,output,size,null,null);output.flush();}
    @Override public void close(){if(listener!=null)try{listener.close();}catch(IOException ignored){}workers.shutdownNow();}
}
